class Solution {
public:
    int minAbsoluteDifference(vector<int>& nums, int x) {
        set<int> st;
        int ans = 2e9;
        for (int i = x; i < nums.size(); ++i) {
            st.insert(nums[i - x]);
            auto it = st.lower_bound(nums[i]);
            if (it != st.end()) ans = min(ans, abs(*it - nums[i]));
            if (it != st.begin()) ans = min(ans, abs(*prev(it) - nums[i]));
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minAbsoluteDifference(List<Integer> nums, int x) {
        TreeSet<Integer> set = new TreeSet<>();
        int ans = Integer.MAX_VALUE;
        for (int i = x; i < nums.size(); i++) {
            set.add(nums.get(i - x));
            int target = nums.get(i);
            Integer ceil = set.ceiling(target);
            if (ceil != null) ans = Math.min(ans, Math.abs(ceil - target));
            Integer floor = set.floor(target);
            if (floor != null) ans = Math.min(ans, Math.abs(floor - target));
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} x
 * @return {number}
 */
var minAbsoluteDifference = function(nums, x) {
    const window = [];
    let ans = Infinity;
    function bisectLeft(arr, val) {
        let l = 0, r = arr.length;
        while (l < r) {
            const m = Math.floor((l + r) / 2);
            if (arr[m] < val) l = m + 1;
            else r = m;
        }
        return l;
    }
    for (let i = x; i < nums.length; i++) {
        const insertVal = nums[i - x];
        const pos = bisectLeft(window, insertVal);
        window.splice(pos, 0, insertVal);
        const target = nums[i];
        const idx = bisectLeft(window, target);
        if (idx < window.length) ans = Math.min(ans, Math.abs(window[idx] - target));
        if (idx > 0) ans = Math.min(ans, Math.abs(window[idx - 1] - target));
    }
    return ans;
};
